sys_script.script:
(function executeRule(current, previous) {
    var requestType = current.getValue('request_type');
    var currentPriority = current.getValue('priority');

    // Set priority based on request type if still at default
    if (currentPriority === 'medium' || !currentPriority) {
        switch (requestType) {
            case 'repair':
            case 'replacement':
                current.setValue('priority', 'high');
                break;
            case 'new_order':
                current.setValue('priority', 'medium');
                break;
            case 'maintenance':
                current.setValue('priority', 'low');
                break;
            default:
                current.setValue('priority', 'medium');
        }
    }
})(current, previous);
